package app.dawnbreaker.mobile;
import android.app.Activity;import android.content.*;import android.net.*;import com.getcapacitor.*;import com.getcapacitor.annotation.*;import androidx.activity.result.ActivityResult;import org.json.*;import java.util.concurrent.*;
@CapacitorPlugin(name="DawnDevice")
public class DawnDevicePlugin extends Plugin{
 private final ExecutorService worker=Executors.newSingleThreadExecutor();
 @PluginMethod public void action(PluginCall call){String command=call.getString("command","");JSObject options=call.getObject("options",new JSObject());
  if(command.equals("warp.start")){Intent consent=android.net.VpnService.prepare(getContext());if(consent!=null){startActivityForResult(call,consent,"vpnConsent");return;}startVpn(call,options);return;}
  if(command.equals("wallpaper.pick")||command.equals("wallpaper.import")){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE);String kind=options.optString("kind");i.setType(command.endsWith("import")?"*/*":kind.equals("image")?"image/*":kind.equals("video")?"video/*":"*/*");startActivityForResult(call,i,"pickResource");return;}
  if(command.equals("wallpaper.export")){Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("application/zip").putExtra(Intent.EXTRA_TITLE,"破晓壁纸.dawnwallpaper");startActivityForResult(call,i,"exportResource");return;}
  if(command.equals("cloud.open")){if(android.os.Build.VERSION.SDK_INT<28){call.reject("隔离网盘窗口需要 Android 9 或更新版本");return;}try{DawnCloudActivity.validateStart(options.optString("provider"),options.optString("url"));getActivity().startActivity(new Intent(getContext(),DawnCloudActivity.class).putExtra("provider",options.optString("provider")).putExtra("url",options.optString("url")));call.resolve(new JSObject().put("message","已打开独立网盘窗口。登录后选择文件，使用 LinkSwift 解析下载。"));}catch(Exception e){call.reject("请输入支持的网盘 HTTPS 页面地址");}return;}
  if(command.equals("cloud.jobs")){call.resolve(new JSObject().put("jobs",new JSArray()));return;}
  worker.execute(()->{try{JSONObject result;if(command.startsWith("warp."))result=DawnWarpService.action(getContext(),command,options);else if(command.startsWith("wallpaper."))result=new WallpaperProjects(getContext(),RemoteOrigin.base(bridge)).action(command,options,getActivity());else throw new Exception("未知操作");call.resolve(JSObject.fromJSONObject(result));}catch(Exception e){call.reject(e.getMessage()==null?"设备操作失败":e.getMessage());}});
 }
 private void startVpn(PluginCall call,JSObject options){worker.execute(()->{try{DawnWarpService.prepare(getContext(),options);Intent i=new Intent(getContext(),DawnWarpService.class);androidx.core.content.ContextCompat.startForegroundService(getContext(),i);for(int n=0;n<200;n++){Thread.sleep(100);if(DawnWarpService.running||!DawnWarpService.error.isEmpty())break;}if(!DawnWarpService.running)throw new Exception(DawnWarpService.error.isEmpty()?"VPN 启动超时":DawnWarpService.error);call.resolve(JSObject.fromJSONObject(DawnWarpService.action(getContext(),"warp.status",new JSONObject())));}catch(Exception e){call.reject(e.getMessage()==null?"VPN 启动失败":e.getMessage());}});}
 @ActivityCallback private void vpnConsent(PluginCall call,ActivityResult result){if(call==null)return;if(result.getResultCode()!=Activity.RESULT_OK){call.reject("未获得系统 VPN 授权");return;}startVpn(call,call.getObject("options",new JSObject()));}
 @ActivityCallback private void pickResource(PluginCall call,ActivityResult result){if(call==null)return;if(result.getResultCode()!=Activity.RESULT_OK||result.getData()==null||result.getData().getData()==null){call.resolve(new JSObject().put("cancelled",true));return;}Uri uri=result.getData().getData();worker.execute(()->{try{WallpaperProjects p=new WallpaperProjects(getContext(),RemoteOrigin.base(bridge));JSONObject picked=p.pick(uri);if(call.getString("command","").equals("wallpaper.import"))picked=p.installPicked(picked.getString("handle"));call.resolve(JSObject.fromJSONObject(picked));}catch(Exception e){call.reject(e.getMessage());}});}
 @ActivityCallback private void exportResource(PluginCall call,ActivityResult result){if(call==null)return;if(result.getResultCode()!=Activity.RESULT_OK||result.getData()==null){call.resolve(new JSObject().put("cancelled",true));return;}worker.execute(()->{try{new WallpaperProjects(getContext(),RemoteOrigin.base(bridge)).export(call.getObject("options").getString("id"),result.getData().getData());call.resolve();}catch(Exception e){call.reject("导出壁纸失败");}});}
}
